<?php
// Public booking page: book.php?t=LEAD_TOKEN (personal link) or book.php?g=BOOKING_KEY (general link)
require __DIR__.'/app/bootstrap.php';
session_write_close();
$t=preg_replace('/[^a-f0-9]/','',$_GET['t']??'');$g=preg_replace('/[^a-f0-9]/','',$_GET['g']??'');
$lead=$t?DB::row('SELECT * FROM leads WHERE token=?',[$t]):null;
if(!$lead&&(!$g||!hash_equals(setting('booking_key'),$g))){http_response_code(404);exit('This booking link is not valid.');}
$err='';$done=null;
if(($_SERVER['REQUEST_METHOD']??'')==='POST'){
  try{
    $start=(int)($_POST['slot']??0);
    $slots=Booking::slots(21);$ok=false;foreach($slots as $day)if(in_array($start,$day,true))$ok=true;
    if(!$ok)throw new Exception('Please choose an available time.');
    if(!$lead){
      $name=trim($_POST['name']??'');$phone=trim($_POST['phone']??'');
      if($name===''||$phone==='')throw new Exception('Please enter your name and phone number.');
      $lid=CRM::create(['contact_name'=>$name,'name'=>trim($_POST['company']??'')?:$name,'phone'=>$phone,'email'=>trim($_POST['email']??''),'message'=>trim($_POST['notes']??'')],'booking','Booking page');}
    else $lid=$lead['id'];
    Booking::book($lid,$start,'lead',trim($_POST['notes']??''));
    $done=$start;}
  catch(Throwable $e){$err=$e->getMessage();}}
$slots=Booking::slots(21);
$P=setting('brand_primary','#0B0B0B');$A=setting('brand_accent','#B8860B');
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Book a time · <?=e(setting('company_name'))?></title><link href="https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600&family=Inter+Tight:wght@600;700&display=swap" rel="stylesheet"><style>*{box-sizing:border-box}body{margin:0;font:15px/1.5 Inter,system-ui,sans-serif;background:#f4f6fb;color:#14213d}.w{max-width:880px;margin:0 auto;padding:24px 16px}.hd{background:<?=e($P)?>;color:#fff;border-radius:18px;padding:26px;display:flex;gap:18px;align-items:center}.hd img{height:64px}.hd h1{font:700 24px 'Inter Tight',sans-serif;margin:0}.hd p{margin:4px 0 0;opacity:.8}.c{background:#fff;border-radius:18px;padding:24px;margin-top:18px;box-shadow:0 6px 24px rgba(20,33,61,.06)}h2{font:700 18px 'Inter Tight',sans-serif;margin:0 0 14px}.days{display:flex;gap:8px;overflow-x:auto;padding-bottom:6px}.day{flex:none;border:1.5px solid #e3e7f0;border-radius:12px;padding:10px 14px;text-align:center;cursor:pointer;min-width:78px;background:#fff}.day b{display:block;font-size:20px}.day small{color:#667;text-transform:uppercase;font-size:11px;letter-spacing:.06em}.day.on{border-color:<?=e($A)?>;background:<?=e($A)?>;color:#fff}.day.on small{color:#fff}.times{display:grid;grid-template-columns:repeat(auto-fill,minmax(96px,1fr));gap:8px;margin-top:16px}.times label{border:1.5px solid #e3e7f0;border-radius:10px;padding:10px;text-align:center;cursor:pointer;font-weight:600}.times input{display:none}.times input:checked+span{color:<?=e($A)?>}.times label:has(input:checked){border-color:<?=e($A)?>;background:#fff8e6}.f{display:grid;grid-template-columns:1fr 1fr;gap:12px;margin-top:16px}.f input,.f textarea{width:100%;padding:12px;border:1.5px solid #e3e7f0;border-radius:10px;font:inherit}.f .full{grid-column:1/-1}button{margin-top:18px;width:100%;padding:15px;border:0;border-radius:12px;background:<?=e($A)?>;color:#fff;font:600 16px Inter,sans-serif;cursor:pointer}.err{background:#fdecec;color:#991b1b;padding:12px;border-radius:10px;margin-bottom:12px}.ok{text-align:center;padding:30px}.ok div{font-size:54px}.meta{display:flex;gap:16px;color:#556;font-size:14px;flex-wrap:wrap;margin-top:6px}@media(max-width:560px){.f{grid-template-columns:1fr}}</style></head><body><div class="w"><div class="hd"><img src="<?=e(base_url(setting('company_logo')))?>" alt=""><div><h1><?=e(setting('appt_title','Book a meeting'))?></h1><p><?=e(setting('company_name'))?><?=$lead?' · for '.e($lead['name']):''?></p><div class="meta"><span>⏱ <?=(int)setting('appt_slot','30')?> minutes</span><span>📍 <?=e(setting('appt_location'))?></span></div></div></div>
<?php if($done):?><div class="c ok"><div>✅</div><h2>You're booked!</h2><p><?=e(date('l, d M Y · h:i A',$done))?></p><p style="color:#667">A confirmation has been sent. We look forward to speaking with you.</p></div>
<?php else:?><form class="c" method="post"><?php if($err):?><div class="err"><?=e($err)?></div><?php endif?><h2>1. Pick a day</h2><?php if(!$slots):?><p>No free slots right now. Please call <?=e(setting('company_phone'))?>.</p><?php else:?><div class="days"><?php $i=0;foreach($slots as $d=>$ts):?><div class="day <?=$i===0?'on':''?>" data-d="<?=$d?>"><small><?=date('D',strtotime($d))?></small><b><?=date('d',strtotime($d))?></b><small><?=date('M',strtotime($d))?></small></div><?php $i++;endforeach?></div><h2 style="margin-top:22px">2. Pick a time</h2><?php $i=0;foreach($slots as $d=>$ts):?><div class="times" data-t="<?=$d?>" <?=$i?'hidden':''?>><?php foreach($ts as $s):?><label><input type="radio" name="slot" value="<?=$s?>" required><span><?=date('h:i A',$s)?></span></label><?php endforeach?></div><?php $i++;endforeach?>
<?php if(!$lead):?><h2 style="margin-top:22px">3. Your details</h2><div class="f"><input name="name" placeholder="Your name" required><input name="phone" placeholder="Phone / WhatsApp" required><input name="email" type="email" placeholder="Email"><input name="company" placeholder="Business name"><textarea class="full" name="notes" placeholder="What would you like to discuss?"></textarea></div><?php else:?><div class="f"><textarea class="full" name="notes" placeholder="Anything you'd like us to prepare? (optional)"></textarea></div><?php endif?><button>Confirm booking</button><?php endif?></form><?php endif?></div>
<script>document.querySelectorAll('.day').forEach(function(d){d.onclick=function(){document.querySelectorAll('.day').forEach(function(x){x.classList.remove('on')});d.classList.add('on');document.querySelectorAll('.times').forEach(function(t){t.hidden=t.dataset.t!==d.dataset.d})}})</script></body></html>
<?php Cron::kick();
